const KIND_HINTS = [['storyboards', /storyboard|concept study|signal-based|localized rich media/i], ['playbook', /playbook|field guide/i], ['package', /package|holiday|seasonal/i], ['competitive', /competitive|spend analysis|share of voice|competitor/i], ['audit', /audit|executive snapshot|digital read|growth read/i], ['market', /market intelligence|rfp|county|insights/i], ['partnership', /partnership|agency partner|embedded|pov|white.?label/i], ['showcase', /showcase|creative suite|gallery/i], ['proposal', /proposal|media plan|budget|flight|rfp|campaign/i]];
const VERTS = {"Education":"universit|college|enrollment|higher ed","Financial Services":"\\bbank|credit union|financial|lender|mortgage|insurance","Healthcare & Senior Care":"healthcare|patient|senior living|clinic|hospital|anesthes|infusion|blood don|ophthalm","Public Sector":"\\bdmv\\b|state agency|public sector|government","Utilities & Energy":"utilit|energy|broadband|internet service","Travel & Tourism":"tourism|travel|destination|resort|hotel|lake of the ozarks","Home Services":"hvac|plumb|roofing|pest|basement|foundation repair|home services|blinds|landscap|remodel|tree service","Automotive":"automotive|dealer|vehicle","Health & Wellness":"wellness|supplement|fitness|footwear","Non-Profit":"nonprofit|non-profit|charity","Food & Beverage":"restaurant|qsr|\\bbeer|whiskey|beverage|chicken|bubble tea|mcdonald","Entertainment":"entertainment|concert|casino|costume|flowers","Sports":"athletic|sports|\\bfc\\b|tennis|stadium|soccer|betting","Retail":"retail|furnish|garden center|shopper|jewel|electronics","Lottery":"lottery|raffle"};
export function guessKind(text) { const t = String(text || ''); const h = KIND_HINTS.find(([, r]) => r.test(t)); return h ? h[0] : 'proposal'; }
export function guessVertical(text) { const t = String(text || ''); let best = '', bs = 0; for (const k in VERTS) { const n = (t.match(new RegExp(VERTS[k], 'gi')) || []).length; if (n > bs) { bs = n; best = k; } } return best; }
/* Returns a text block of the n closest exemplar outlines, or '' when nothing fits. */
export function relevantPages(i, n = 2) {
  const head = [i.title, i.brand, i.agency].filter(Boolean).join(' '), body = String(i.briefText || i.brief || '').slice(0, 12000);
  const kind = guessKind(head + ' ' + body.slice(0, 3000)), vert = (i.vertical && VERTS[i.vertical] ? i.vertical : '') || guessVertical(head + ' ' + body);
  const brand = String(i.brand || '').toLowerCase().trim();
  const scored = EXEMPLARS.map(e => ({ e, s: (e.k === kind ? 4 : 0) + (vert && e.v === vert ? 3 : 0) + (brand && brand.length > 2 && (e.c + ' ' + e.t).toLowerCase().includes(brand) ? 6 : 0) })).filter(x => x.s >= 3).sort((a, b) => b.s - a.s).slice(0, n);
  if (!scored.length) return '';
  return 'RELEVANT PAST PAGES (archetype: ' + kind + (vert ? ', vertical: ' + vert : '') + '). Outlines of published KORTX pages in reading order; match their structure and headline style, never their facts:\n' + scored.map(({ e }) => '- [' + e.k + ' · ' + e.v + '] ' + e.t + ' (' + e.c + ')\n  ' + e.o).join('\n');
}
